function validateStep(){
  let ok=true,message="Bitte alle Pflichtfelder ausfüllen";
  if(currentStep===0)form.querySelectorAll('[data-step="0"] [required]').forEach(el=>{el.classList.toggle("invalid",!el.value.trim());if(!el.value.trim())ok=false});
  if(currentStep===1&&!selectedAreas().length){ok=false;message="Bitte mindestens einen Arbeitsbereich aktiv auswählen"}
  if([2,3,4,5].includes(currentStep)){
    const kind={2:"work",3:"vehicles",4:"equipment",5:"materials"}[currentStep];
    selectedAreas().forEach(key=>{const use=document.querySelector(`[data-use="${kind}:${key}"]`);if(!use?.value){use?.classList.add("invalid");ok=false;return}use.classList.remove("invalid");if(use.value==="none")return;
      if(kind==="work"&&!([...document.querySelectorAll(`[data-work="${key}"] .entry-row`)].some(row=>row.querySelector('[data-field="firstName"]')?.value.trim()&&row.querySelector('[data-field="lastName"]')?.value.trim()&&Number(row.querySelector('[data-field="hours"]')?.value)>0&&row.querySelector('[data-field="role"]')?.value&&row.querySelector('[data-field="description"]')?.value)))ok=false;
      if(kind==="vehicles"&&!([...document.querySelectorAll(`[data-vehicles="${key}"] .entry-row`)].some(row=>row.querySelector('[data-field="type"]')?.value==="Kein Fahrzeug"||Number(row.querySelector('[data-field="count"]')?.value)>0)))ok=false;
      if(kind==="equipment"&&!([...document.querySelectorAll(`[data-equipment="${key}"] .entry-row`)].some(row=>row.querySelector('[data-field="item"]')?.value.trim()&&(Number(row.querySelector('[data-field="quantity"]')?.value)>0||(row.querySelector('[data-field="built"]')?.value&&row.querySelector('[data-field="removed"]')?.value)))))ok=false;
      if(kind==="materials"&&!([...document.querySelectorAll(`[data-products="${key}"] [data-field="amount"],[data-consumables="${key}"] [data-field="amount"],[data-disposal-amount="${key}"]`)].some(x=>Number(x.value)>0)))ok=false;
    });
  }
  if(currentStep===6){const el=form.insurance;el.classList.toggle("invalid",!el.value.trim());if(!el.value.trim())ok=false}
  if(currentStep===6&&form.inspectorEmail.value&&!form.inspectorEmail.checkValidity()){form.inspectorEmail.classList.add("invalid");ok=false}
  if(!ok)toast(message,true);return ok;
}
