function updatePrices(row){if(!row)return;if(row.classList.contains("vehicle")){const type=row.querySelector('[data-field="type"]')?.value,billing=row.querySelector('[data-field="billing"]')?.value,price=row.querySelector('[data-field="unitPrice"]');if(price)price.value=VEHICLE_PRICES[type]?.[billing]||0}if(row.classList.contains("equipment")){const select=row.querySelector('[data-field="item"]'),code=(select?.value||"").split(" ")[0],item=Object.values(EQUIPMENT).flat().find(x=>x.code===code);if(item){row.querySelector('[data-field="unit"]').value=item.unit;row.querySelector('[data-field="unitPrice"]').value=item.price}}}
function money(value){return Number(value||0).toLocaleString("de-CH",{style:"currency",currency:"CHF"})}
function calculateCosts(r){const flat=x=>Object.values(x||{}).flat(),labour=flat(r.work).reduce((s,x)=>s+(Number(x.hours)||0)*(WORK_PRICES[x.role]||0),0),vehicles=flat(r.vehicles).reduce((s,x)=>s+(Number(x.count)||0)*(Number(x.amount)||0)*(Number(x.unitPrice)||VEHICLE_PRICES[x.type]?.[x.billing]||0),0),equipment=flat(r.equipment).reduce((s,x)=>{let quantity=Number(x.quantity)||0;if(!quantity&&x.built&&x.removed)quantity=Math.max(1,Math.round((new Date(x.removed)-new Date(x.built))/86400000)+1);return s+quantity*(Number(x.unitPrice)||0)},0),materials=[...flat(r.products),...flat(r.consumables)].reduce((s,x)=>s+(Number(x.amount)||0)*(Number(x.unitPrice)||MATERIAL_PRICES[x.item]||0),0),disposal=Object.values(r.disposal||{}).reduce((s,x)=>s+(Number(x.amount)||0)*(x.unit==="m³"?130:0),0),thirdParty=(r.thirdParty||[]).reduce((s,x)=>s+(Number(x.price)||0),0),total=labour+vehicles+equipment+materials+disposal+thirdParty,revenue=Number(r.costs?.invoiceAmount)||0,margin=revenue-total,marginPercent=revenue?margin/revenue*100:0;return{labour,vehicles,equipment,materials:materials+disposal,thirdParty,total,revenue,margin,marginPercent}}
