async function api(path,options={}){const headers={...(options.headers||{}),"X-App-Key":authKey};if(portalToken)headers.Authorization=`Bearer ${portalToken}`;if(options.body)headers["Content-Type"]="application/json";const res=await fetch(path,{...options,headers});if(res.status===401){if(portalToken||new URLSearchParams(location.search).get("portal")==="1")document.querySelector("#leaderLoginDialog").showModal();else document.querySelector("#authDialog").showModal();throw new Error("Zugriff oder Login ungültig")}const data=await res.json();if(!res.ok)throw new Error(data.error||"Anfrage fehlgeschlagen");return data}
async function save(){if(currentStep===6&&!validateStep())return null;try{const result=await api("/api/reports",{method:"POST",body:JSON.stringify(collect())});currentId=result.id;document.querySelector("#saveState").textContent=`Gespeichert · ${new Date().toLocaleTimeString("de-CH",{hour:"2-digit",minute:"2-digit"})}`;toast("Rapport gespeichert");if(currentStep===7)renderReview();return result}catch(e){toast(e.message,true);return null}}
