function renderReportList(){const list=document.querySelector("#reportsList"),query=(document.querySelector("#reportSearch")?.value||"").trim().toLowerCase(),projectStatus=document.querySelector("#projectStatusFilter")?.value||"",reportStatus=document.querySelector("#reportStatusFilter")?.value||"",reports=lastReports.filter(r=>(!query||`${r.projectNumber} ${r.projectName}`.toLowerCase().includes(query))&&(!projectStatus||r.projectStatus===projectStatus)&&(!reportStatus||r.status===reportStatus)),leaders=reports.reduce((all,r)=>{(all[r.projectLead]??={});(all[r.projectLead][r.folderDate||r.date]??=[]).push(r);return all},{});list.innerHTML=reports.length?Object.entries(leaders).map(([leader,dates])=>`<section class="folder"><h3 class="folder-title">${esc(leader)} <small>(${Object.values(dates).flat().length})</small></h3>${Object.entries(dates).sort((a,b)=>b[0].localeCompare(a[0])).map(([date,items])=>`<div class="folder-date"><h4>${esc(date)}</h4>${items.map(r=>reportItem(r,currentReportScope)).join("")}</div>`).join("")}</section>`).join(""):"<p>Keine passenden Rapporte gefunden.</p>";bindReports();translatePage()}
function reportItem(r,scope){let action="";if(r.status==="Entwurf"&&scope==="admin")action=`<button data-workflow="${r.id}:Zur Kontrolle">An PL senden</button>`;if(r.status==="Zur Kontrolle")action=`<select class="office-assign" data-office-for="${r.id}"><option value="">Office auswählen</option>${officeWorkers.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select><button data-workflow="${r.id}:Frontoffice" ${officeWorkers.length?"":"disabled"}>Bestätigen & zuweisen</button>`;if(r.status==="Frontoffice"&&scope==="admin")action=`<button data-workflow="${r.id}:Erledigt">Erledigt</button>`;return `<article class="report-item"><div><h3>${esc(r.projectNumber||"–")} · ${esc(r.projectName||r.title)} <span class="status-pill">${esc(r.status)}</span> <span class="project-status">${esc(r.projectStatus||"Offen")}</span></h3><p>${esc(r.reporterName||"")} · ${esc(r.location||"")} · ${new Date(r.updated_at).toLocaleString("de-CH")}${r.officeWorker?` · Office: ${esc(r.officeWorker)}`:""}</p></div><div class="report-actions"><button data-load="${r.id}">Öffnen / korrigieren</button>${r.hasPdf?`<a href="/api/reports/${r.id}/pdf" data-download="${r.id}:pdf">PDF</a>`:""}<a href="/api/reports/${r.id}/excel" data-download="${r.id}:excel">Excel</a>${action}${scope==="admin"?`<button class="danger" data-delete="${r.id}">Löschen</button>`:""}</div></article>`}
function bindReports(){document.querySelectorAll("[data-load]").forEach(b=>b.onclick=()=>loadReport(b.dataset.load));document.querySelectorAll("[data-delete]").forEach(b=>b.onclick=()=>deleteReport(b.dataset.delete));document.querySelectorAll("[data-download]").forEach(a=>a.onclick=e=>{e.preventDefault();const [id,type]=a.dataset.download.split(":");downloadFile(id,type)});document.querySelectorAll("[data-workflow]").forEach(b=>b.onclick=()=>{const [id,status]=b.dataset.workflow.split(":"),officeWorkerId=status==="Frontoffice"?document.querySelector(`[data-office-for="${id}"]`)?.value:"";if(status==="Frontoffice"&&!officeWorkerId){toast("Bitte zuerst eine Office-Person auswählen",true);return}changeWorkflow(id,status,true,officeWorkerId)})}
