async function submitToLead(){if(!form.insurance.value.trim()){go(6);form.insurance.classList.add("invalid");toast("Bitte die Versicherung angeben",true);return}const saved=await save();if(!saved)return;const result=await changeWorkflow(currentId,"Zur Kontrolle",false);if(result){form.status.value="Zur Kontrolle";document.querySelector("#currentStatus").textContent="Zur Kontrolle";toast(result.mailSent?`PDF erstellt und an ${form.projectLead.value} übermittelt`:`PDF erstellt – E-Mail nicht gesendet: ${result.mailDetail}` ,!result.mailSent)}}
async function downloadFile(id,type){const headers={"X-App-Key":authKey};if(portalToken)headers.Authorization=`Bearer ${portalToken}`;const res=await fetch(`/api/reports/${id}/${type}`,{headers});if(!res.ok){toast(`${type.toUpperCase()}-Download fehlgeschlagen`,true);return}const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=(res.headers.get("content-disposition")?.match(/filename="(.+)"/)||[])[1]||`Tagesrapport.${type}`;a.click();URL.revokeObjectURL(url)}
function applyReport(r){reset(false);currentId=r.id||null;form.date.value=r.date||"";form.reporterName.value=r.reporterName||"";form.region.value=r.region||"";form.projectLead.value=r.projectLead||"";const known=["Feuer","Wasser"].includes(r.damageType);form.damageType.value=known?r.damageType:"Andere";form.damageOther.value=known?"":r.damageType||"";form.projectNumber.value=r.projectNumber||"";form.projectName.value=r.projectName||r.location?.name||"";form.projectStatus.value=r.projectStatus||"Offen";form.locationAddress.value=r.location?.address||"";form.locationCity.value=r.location?.city||"";form.status.value=r.status||"Entwurf";form.notes.value=r.notes||"";const c=r.costs||{};form.insurance.value=c.insurance||"";form.inspectorName.value=c.inspectorName||"";form.inspectorEmail.value=c.inspectorEmail||"";form.claimNumber.value=c.claimNumber||"";form.invoiceAmount.value=c.invoiceAmount||"";document.querySelector("#currentStatus").textContent=form.status.value;form.querySelectorAll('[name="areas"]').forEach(x=>x.checked=(r.areas||[]).includes(x.value));renderDynamic();renderThirdParty(r.thirdParty||[]);restoreGroups(r);toggleDamage();updateCostSummary();document.querySelector("#saveState").textContent="Gespeicherter Rapport"}
function restoreGroups(r){for(const key of r.areas||[]){const work=(r.work?.[key]||[]).map(x=>{if(x.name&&!x.firstName&&!x.lastName){const parts=x.name.trim().split(/\s+/);return{...x,firstName:parts.shift()||"",lastName:parts.join(" ")}}return x});fillRows(`[data-work="${key}"]`,work,x=>workRow(key,x));fillRows(`[data-vehicles="${key}"]`,r.vehicles?.[key],x=>vehicleRow(x.type,x));fillRows(`[data-equipment="${key}"]`,r.equipment?.[key],x=>equipmentRow(key,x));fillRows(`[data-products="${key}"]`,r.products?.[key],x=>materialRow(x.item,x));fillRows(`[data-consumables="${key}"]`,r.consumables?.[key],x=>materialRow(x.item,x));for(const kind of ["work","vehicles","equipment","materials"]){const el=document.querySelector(`[data-use="${kind}:${key}"]`);if(el)el.value=r.usage?.[key]?.[kind]||"used"}Object.entries(r.extras?.[key]||{}).forEach(([field,value])=>{const el=document.querySelector(`[data-extra="${key}:${field}"]`);if(el)el.value=value});const entry=r.disposal?.[key]||{};const disp=document.querySelector(`[data-disposal="${key}"]`);if(disp)disp.value=typeof entry==="string"?entry:entry.method||"";const amount=document.querySelector(`[data-disposal-amount="${key}"]`);if(amount)amount.value=entry.amount||"";const unit=document.querySelector(`[data-disposal-unit="${key}"]`);if(unit)unit.value=entry.unit||"kg"}bindRemove()}
function fillRows(selector,items,render){if(!items?.length)return;const c=document.querySelector(selector);c.innerHTML=items.map(render).join("");[...c.querySelectorAll(".entry-row")].forEach((row,i)=>Object.entries(items[i]).forEach(([k,v])=>{const el=row.querySelector(`[data-field="${k}"]`);if(el)el.value=v??""}))}
function renderReview(){const r=collect(),c=calculateCosts(r),hours=Object.values(r.work).flat().reduce((sum,x)=>sum+(Number(x.hours)||0),0),material=Object.values(r.products).flat().filter(x=>x.amount).length+Object.values(r.consumables).flat().filter(x=>x.amount).length;document.querySelector("#currentStatus").textContent=r.status;document.querySelector("#review").innerHTML=`<div class="review-card"><h3>Einsatz</h3><dl><div><dt>Datum</dt><dd>${esc(r.date)}</dd></div><div><dt>Ausgefüllt von</dt><dd>${esc(r.reporterName||"–")}</dd></div><div><dt>Projektleiter</dt><dd>${esc(r.projectLead||"–")}</dd></div><div><dt>Schaden</dt><dd>${esc(r.damageType||"–")}</dd></div></dl></div><div class="review-card"><h3>Projekt</h3><dl><div><dt>Projektnummer</dt><dd>${esc(r.projectNumber||"–")}</dd></div><div><dt>Projektname</dt><dd>${esc(r.projectName||"–")}</dd></div><div><dt>Projektstatus</dt><dd>${esc(r.projectStatus||"–")}</dd></div><div><dt>Versicherung</dt><dd>${esc(r.costs.insurance||"–")}</dd></div><div><dt>Schadennummer</dt><dd>${esc(r.costs.claimNumber||"–")}</dd></div></dl></div><div class="review-card"><h3>Umfang</h3><dl><div><dt>Bereiche</dt><dd>${r.areas.map(x=>AREAS[x]).join(", ")||"–"}</dd></div><div><dt>Arbeitsstunden</dt><dd>${hours.toLocaleString("de-CH")} Std.</dd></div><div><dt>Materialpositionen</dt><dd>${material}</dd></div></dl></div><div class="review-card"><h3>Kostenübersicht</h3><dl><div><dt>Gesamtkosten</dt><dd>${money(c.total)}</dd></div><div><dt>Verrechenbar</dt><dd>${money(c.revenue)}</dd></div><div><dt>Marge</dt><dd>${money(c.margin)} · ${c.marginPercent.toFixed(1)}%</dd></div></dl></div><div class="review-card"><h3>Weitergabe</h3><p>Der Rapport wird als PDF in den Tagesordner von «${esc(r.projectLead||"Projektleiter") }» gelegt. Der Projektleiter erhält eine E-Mail mit Login-Link, kann korrigieren und anschliessend ans Frontoffice weitergeben.</p></div>`;translatePage()}
function renderDetailedReview(){const r=collect(),rows=Object.entries(r.work).flatMap(([area,items])=>items.filter(x=>reportPerson(x)&&Number(x.hours)>0).map(x=>({area,...x})));if(!rows.length)return;document.querySelector("#review").insertAdjacentHTML("beforeend",`<div class="review-card review-wide"><h3>Mitarbeiterdetails</h3><div class="table-scroll"><table class="hours-table"><thead><tr><th>Mitarbeiter</th><th>Bereich</th><th>Arbeitsbeschrieb</th><th>Stunden</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(reportPerson(x))}</td><td>${esc(AREAS[x.area])}</td><td>${esc(x.description||x.role||"–")}</td><td>${Number(x.hours).toLocaleString("de-CH")}</td></tr>`).join("")}</tbody></table></div></div>`)}
function reportPerson(x){return `${x.firstName||""} ${x.lastName||x.name||""}`.trim()}
function reset(confirmFirst=true){if(confirmFirst&&!confirm("Aktuellen Rapport verwerfen und neu beginnen?"))return;currentId=null;form.reset();form.date.value=new Date().toISOString().slice(0,10);form.status.value="Entwurf";document.querySelector("#currentStatus").textContent="Entwurf";currentStep=0;renderDynamic();renderThirdParty();toggleDamage();updateCostSummary();updateStep();document.querySelector("#saveState").textContent="Noch nicht gespeichert"}
function switchDialogTab(name){document.querySelectorAll("[data-dialog-tab]").forEach(x=>x.classList.toggle("active",x.dataset.dialogTab===name));document.querySelector("#reportsList").classList.toggle("hidden",name!=="folders");document.querySelector("#hoursList").classList.toggle("hidden",name!=="hours");if(name==="hours")loadHours()}
async function leaderLogin(){const name=document.querySelector("#leaderLoginName").value,password=document.querySelector("#leaderLoginPassword").value,error=document.querySelector("#leaderLoginError");error.textContent="";try{const res=await fetch("/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name,password})}),data=await res.json();if(!res.ok)throw new Error(data.error||"Login fehlgeschlagen");portalToken=data.token;portalLead=data.projectLead;sessionStorage.setItem("leaderToken",portalToken);sessionStorage.setItem("leaderName",portalLead);document.querySelector("#leaderLoginPassword").value="";document.querySelector("#leaderLoginDialog").close();showPortalState();const requested=new URLSearchParams(location.search).get("report");if(requested)await loadReport(requested);else openReports()}catch(e){error.textContent=e.message}}
function openLeaderLogin(){if(!portalToken){document.querySelector("#leaderLoginDialog").showModal();return}if(confirm(`Projektleiter-Login von ${portalLead} abmelden?`)){portalToken="";portalLead="";sessionStorage.removeItem("leaderToken");sessionStorage.removeItem("leaderName");location.href="/"}}
function showPortalState(){const button=document.querySelector("#openLeaderLogin");button.textContent=`Angemeldet: ${portalLead}`;button.classList.add("logged-in-badge");document.querySelector("#openLeaderAccess").style.display="none";document.querySelector("#openEmployees").style.display="none";document.querySelector("#openOfficeWorkers").style.display="none";document.querySelector("#resetButton").style.display="none"}
async function openLeaderAccess(){const dialog=document.querySelector("#leaderAccessDialog"),list=document.querySelector("#leaderAccessList");if(!dialog.open)dialog.showModal();list.innerHTML="<p>Zugänge werden geladen …</p>";try{const {projectLeaders}=await api("/api/project-leaders");list.innerHTML=projectLeaders.map(x=>`<div class="leader-access-row"><div><h3>${esc(x.name)}</h3><p>${esc(x.email)} · ${x.loginConfigured?"Login eingerichtet":"Noch kein Login"}</p></div><label>Neues Passwort<input type="password" minlength="10" data-leader-password="${esc(x.name)}" placeholder="Mindestens 10 Zeichen"></label><button class="primary" data-save-leader="${esc(x.name)}">Passwort setzen</button></div>`).join("");document.querySelectorAll("[data-save-leader]").forEach(button=>button.onclick=()=>saveLeaderPassword(button.dataset.saveLeader));translatePage()}catch(e){list.innerHTML=`<p class="error">${esc(e.message)}</p>`}}
async function saveLeaderPassword(name){const input=document.querySelector(`[data-leader-password="${CSS.escape(name)}"]`);try{await api("/api/project-leaders/password",{method:"POST",body:JSON.stringify({name,password:input.value})});toast(`Login für ${name} gespeichert`);openLeaderAccess()}catch(e){toast(e.message,true)}}
async function loadEmployees(){try{const result=await api("/api/employees");employees=result.employees;document.querySelector("#employeeNames").innerHTML=employees.map(x=>`<option value="${esc(x.name)}"></option>`).join("");const names=employees.map(x=>{const p=x.name.trim().split(/\s+/);return{first:p.shift()||"",last:p.join(" ")}});document.querySelector("#employeeFirstNames").innerHTML=[...new Set(names.map(x=>x.first))].map(x=>`<option value="${esc(x)}"></option>`).join("");document.querySelector("#employeeLastNames").innerHTML=[...new Set(names.map(x=>x.last))].map(x=>`<option value="${esc(x)}"></option>`).join("");renderEmployeeList()}catch(e){if(!String(e.message).includes("Zugriff"))toast(e.message,true)}}
function openEmployees(){document.querySelector("#employeesDialog").showModal();renderEmployeeList()}
function renderEmployeeList(){const list=document.querySelector("#employeesList");list.innerHTML=employees.length?employees.map(x=>`<article class="report-item"><div><strong>${esc(x.name)}</strong>${x.source==="report"?'<p>Vorschlag aus einem früheren Rapport</p>':""}</div>${x.id?`<button class="ghost danger" data-remove-employee="${x.id}">Entfernen</button>`:""}</article>`).join(""):"<p>Noch keine Polygon-Mitarbeitenden gespeichert.</p>";document.querySelectorAll("[data-remove-employee]").forEach(b=>b.onclick=()=>removeEmployee(b.dataset.removeEmployee))}
async function addEmployee(){const input=document.querySelector("#employeeName"),name=input.value.trim();if(!name)return;try{await api("/api/employees",{method:"POST",body:JSON.stringify({name})});input.value="";await loadEmployees();toast("Mitarbeiter gespeichert")}catch(e){toast(e.message,true)}}
async function removeEmployee(id){if(!confirm("Mitarbeiter aus der Auswahl entfernen?"))return;await api(`/api/employees/${id}`,{method:"DELETE"});await loadEmployees()}
async function openOfficeWorkers(){const d=document.querySelector("#officeWorkersDialog");if(!d.open)d.showModal();await loadOfficeWorkers()}
async function loadOfficeWorkers(){const list=document.querySelector("#officeWorkersList");list.innerHTML="<p>Office-Mitarbeitende werden geladen …</p>";try{officeWorkers=(await api("/api/office-workers")).officeWorkers;list.innerHTML=officeWorkers.length?officeWorkers.map(x=>`<article class="report-item"><div><strong>${esc(x.name)}</strong><p>${esc(x.email)}</p></div><button class="ghost danger" data-remove-office="${x.id}">Entfernen</button></article>`).join(""):"<p>Noch keine Office-Mitarbeitenden erfasst.</p>";document.querySelectorAll("[data-remove-office]").forEach(b=>b.onclick=()=>removeOfficeWorker(b.dataset.removeOffice))}catch(e){list.innerHTML=`<p class="error">${esc(e.message)}</p>`}}
async function addOfficeWorker(){const name=document.querySelector("#officeWorkerName").value.trim(),email=document.querySelector("#officeWorkerEmail").value.trim();try{await api("/api/office-workers",{method:"POST",body:JSON.stringify({name,email})});document.querySelector("#officeWorkerName").value="";document.querySelector("#officeWorkerEmail").value="";await loadOfficeWorkers();toast("Office-Mitarbeiter gespeichert")}catch(e){toast(e.message,true)}}
async function removeOfficeWorker(id){if(!confirm("Office-Mitarbeiter aus der Auswahl entfernen?"))return;await api(`/api/office-workers/${id}`,{method:"DELETE"});await loadOfficeWorkers()}
async function loadHours(){const box=document.querySelector("#hoursTable"),ids={from:"hoursFrom",to:"hoursTo",region:"hoursRegion",employee:"hoursEmployee",project:"hoursProject",lead:"hoursLead",area:"hoursArea",projectStatus:"hoursProjectStatus",reportStatus:"hoursReportStatus"},params=new URLSearchParams();Object.entries(ids).forEach(([key,id])=>{const value=document.querySelector(`#${id}`)?.value;if(value)params.set(key,value)});box.innerHTML="<p>Stunden werden berechnet …</p>";try{const data=await api(`/api/hour-summary?${params}`);const setOptions=(id,values)=>{const el=document.querySelector(`#${id}`),old=el.value;el.innerHTML='<option value="">Alle</option>'+values.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join("");el.value=old};for(const [key,id] of Object.entries({regions:"hoursRegion",employees:"hoursEmployee",projects:"hoursProject",leads:"hoursLead",projectStatuses:"hoursProjectStatus",reportStatuses:"hoursReportStatus"}))setOptions(id,data.filterOptions?.[key]||[]);const pivots=data.pivot||[],details=data.details||[];box.innerHTML=pivots.length?pivots.map(group=>`<section class="pivot-region"><h3>${esc(group.region)}</h3><table class="hours-table"><thead><tr><th>Mitarbeiter</th><th>Fahrhabe</th><th>Gebäude</th><th>Trocknung</th><th>Total</th></tr></thead><tbody>${group.rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.fh}</td><td>${x.gb}</td><td>${x.tr}</td><td><strong>${x.total}</strong></td></tr>`).join("")}</tbody></table></section>`).join("")+`<h3>Detailansicht</h3><div class="table-scroll"><table class="hours-table"><thead><tr><th>Datum</th><th>Projekt</th><th>Mitarbeiter</th><th>Region</th><th>Bereich</th><th>Arbeitsbeschrieb</th><th>Stunden</th><th>Projektleiter</th><th>Status</th></tr></thead><tbody>${details.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.projectNumber)} · ${esc(x.projectName)}</td><td>${esc(x.name)}</td><td>${esc(x.region)}</td><td>${esc(AREAS[x.area])}</td><td>${esc(x.description||"–")}</td><td>${x.hours}</td><td>${esc(x.projectLead)}</td><td>${esc(x.reportStatus)}</td></tr>`).join("")}</tbody></table></div>`:"<p>Für die Auswahl wurden keine Arbeitsstunden gefunden.</p>"}catch(e){box.innerHTML=`<p class="error">${esc(e.message)}</p>`}}
function setLanguage(language){currentLanguage=["de","fr","it"].includes(language)?language:"de";localStorage.setItem("rapportLanguage",currentLanguage);document.documentElement.lang=currentLanguage;document.querySelector("#languageSelect").value=currentLanguage;updateStep();translatePage()}
function translatePage(){const dictionary=TRANSLATIONS[currentLanguage]||{};document.querySelectorAll("option").forEach(option=>{if(!option.hasAttribute("value"))option.setAttribute("value",option.textContent.trim())});const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.textContent.trim())continue;if(!originalText.has(node))originalText.set(node,node.textContent);const base=originalText.get(node),trimmed=base.trim(),translated=dictionary[trimmed];node.textContent=translated?base.replace(trimmed,translated):base}document.querySelectorAll("input[placeholder],textarea[placeholder]").forEach(el=>{if(!originalPlaceholder.has(el))originalPlaceholder.set(el,el.placeholder);const base=originalPlaceholder.get(el);el.placeholder=dictionary[base]||base})}
function toast(message,error=false){const t=document.querySelector("#toast");t.textContent=message;t.style.background=error?"#9b2f3b":"";t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2800)}
init();
